function GlassColorantSpatulaMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassColorantSpatulaMaker.maker={name=n or ("Lopatičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatičar najet: %s (spretnost: %d)",GlassColorantSpatulaMaker.maker.name,s),"success") end; return true end
function GlassColorantSpatulaMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassColorantSpatulaMaker.build(id) local ok,e=GlassColorantSpatulaMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassColorantSpatulaMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassColorantSpatulaMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassColorantSpatulaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassColorantSpatulaMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassColorantSpatulaMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassColorantSpatulaMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassColorantSpatulaMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassColorantSpatulaMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassColorantSpatulaMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassColorantSpatulaMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassColorantSpatulaMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassColorantSpatulaMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassColorantSpatulaMaker.buildings==0 then return false,"Potrebna lopaticna delavnica" end; if not GlassColorantSpatulaMaker.maker then return false,"Potreben lopaticar" end; return true end
function GlassColorantSpatulaMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassColorantSpatulaMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassColorantSpatulaMaker.ironStock=GlassColorantSpatulaMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassColorantSpatulaMaker.bronzeStock=GlassColorantSpatulaMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassColorantSpatulaMaker.woodStock=GlassColorantSpatulaMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassColorantSpatulaMaker.leatherStock=GlassColorantSpatulaMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassColorantSpatulaMaker.silverStock=GlassColorantSpatulaMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassColorantSpatulaMaker.goldStock=GlassColorantSpatulaMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassColorantSpatulaMaker.jewelStock=GlassColorantSpatulaMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassColorantSpatulaMaker.pearlStock=GlassColorantSpatulaMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassColorantSpatulaMaker.maker then t=math.max(1,t-math.floor(GlassColorantSpatulaMaker.maker.skill/13)) end; table.insert(GlassColorantSpatulaMaker.activeMaking,{id="glasscolorantspatula_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassColorantSpatulaMaker.completeMaking(m) local q=1.0+(GlassColorantSpatulaMaker.getQualityBonus()/100); if GlassColorantSpatulaMaker.maker then q=q+(GlassColorantSpatulaMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantSpatulaMaker.productStock[m.productType]=(GlassColorantSpatulaMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantSpatulaMaker.totalProducts=GlassColorantSpatulaMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantSpatulaMaker.maker then GlassColorantSpatulaMaker.maker.itemsMade=GlassColorantSpatulaMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantSpatulaMaker.maker.skill=math.min(100,GlassColorantSpatulaMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorantspatula.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantSpatulaMaker.update(dt) if not _G.state then return end; GlassColorantSpatulaMaker.dayTimer=GlassColorantSpatulaMaker.dayTimer+dt; if GlassColorantSpatulaMaker.dayTimer>=30 then GlassColorantSpatulaMaker.dayTimer=0; for i=#GlassColorantSpatulaMaker.activeMaking,1,-1 do local m=GlassColorantSpatulaMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantSpatulaMaker.completeMaking(m); table.remove(GlassColorantSpatulaMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantSpatulaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantSpatulaMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
